using Alterverse.Combat;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Match
{
public sealed class DimensionPlanetDirector:MonoBehaviour
{
private const float FirstSpawn=120f,SecondSpawn=300f,Warning=15f;private static DimensionPlanetDirector active;private float elapsed;private bool warnedFirst,warnedSecond,spawnedFirst,spawnedSecond;private DimensionsFront front;public static string Announcement{get;private set;}public static float AnnouncementUntil{get;private set;}public static float FirstSpawnRemaining=>Mathf.Max(0,FirstSpawn-(active!=null?active.elapsed:FirstSpawn));public static float SecondSpawnRemaining=>Mathf.Max(0,SecondSpawn-(active!=null?active.elapsed:SecondSpawn));private void Awake(){active=this;elapsed=0;warnedFirst=warnedSecond=spawnedFirst=spawnedSecond=false;Announcement=null;AnnouncementUntil=0;front=FindAnyObjectByType<DimensionsFront>();}private void OnDestroy(){if(active==this){active=null;Announcement=null;AnnouncementUntil=0;}}
private void Update(){if(Time.timeScale<=0f)return;if(front==null)front=FindAnyObjectByType<DimensionsFront>();if(front!=null&&front.HasEnded)return;elapsed+=Time.deltaTime;if(!warnedFirst&&elapsed>=FirstSpawn-Warning){warnedFirst=true;Announce("FLUX PLANET SPAWNS IN 15 SECONDS — CENTER FRONT");}if(!spawnedFirst&&elapsed>=FirstSpawn){spawnedFirst=true;SpawnPlanet("DF_FluxPlanet",new Vector3(0,1.25f,3.2f),PlanetBuffType.Flux,320,StylizedArtDirection.LumenEnergy);Announce("FLUX PLANET ACTIVE — CENTER FRONT");}if(!warnedSecond&&elapsed>=SecondSpawn-Warning){warnedSecond=true;Announce("GUARD PLANET SPAWNS IN 15 SECONDS — CENTER FRONT");}if(!spawnedSecond&&elapsed>=SecondSpawn){spawnedSecond=true;SpawnPlanet("DF_GuardPlanet",new Vector3(0,1.25f,-3.2f),PlanetBuffType.Guard,460,StylizedArtDirection.WarmAccent);Announce("GUARD PLANET ACTIVE — CENTER FRONT");}}
private static void Announce(string text){Announcement=text;AnnouncementUntil=Time.unscaledTime+4f;}private static void SpawnPlanet(string name,Vector3 p,PlanetBuffType type,float hp,Color color){GameObject root=GameObject.CreatePrimitive(PrimitiveType.Sphere);root.name=name;root.transform.position=p;root.transform.localScale=Vector3.one*1.65f;Renderer r=root.GetComponent<Renderer>();if(r!=null)r.material.color=color;for(int i=0;i<4;i++){GameObject shard=GameObject.CreatePrimitive(PrimitiveType.Cube);shard.name="DF_PlanetShard";shard.transform.SetParent(root.transform,false);float a=i*Mathf.PI*.5f;shard.transform.localPosition=new Vector3(Mathf.Cos(a)*1.35f,(i%2)*.3f-.15f,Mathf.Sin(a)*1.35f);shard.transform.localScale=new Vector3(.14f,.55f,.14f);shard.transform.rotation=Quaternion.Euler(25,i*90,25);Collider c=shard.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer sr=shard.GetComponent<Renderer>();if(sr!=null)sr.material.color=color;}Health h=root.AddComponent<Health>();h.Configure(hp);DimensionPlanet planet=root.AddComponent<DimensionPlanet>();planet.Initialize(type);root.AddComponent<PlanetPulseAttack>();}
}
}
